with f as (select n.nspname||'.'||p.proname as fq, regexp_replace(regexp_replace(p.prosrc, '--[^\n]*', '', 'g'), '/\*.*?\*/', '', 'g') as src from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in ('crm','private','public') and l.lanname in ('sql','plpgsql')), m as (select fq, r[1]||'.'||r[2] as ref from f, regexp_matches(f.src, '\m(crm|private|public)\.([a-z0-9_]+)', 'g') as r) select fq, string_agg(ref||':'||n, ' ' order by ref) as refs from (select fq, ref, count(*) n from m group by 1,2) x group by fq order by fq
